async function runGit(rootPath, args) {
    try {
        return await runGitWithIndexLockRetries(rootPath, args);
    } catch (error) {
        if (!isSpawnEnoentError(error)) throw error;

        throw await describeSpawnEnoent(rootPath, args, error);
