> export function cardContext(
      card: MarkdownContextCard, cardTypes: CardTypeConfig[], worktrees: readonly WorktreeRecord[] = 
worktreeService.getRecords(),
  ): ActionContext {
      if (!card.header.internalId) throw new Error(`Cannot build action context without an internal ID: ${card.path}`)
  
      return markdownContext(card, cardTypes, 'card', worktrees);
  }
  
  /**
   * Build the action context for a markdown file in the tree/text view. Regular markdown files
   * are not cards and carry no internal ID, so the context stays without card identity.
   */
  export function fileContext(
      card: Card, cardTypes: CardTypeConfig[], worktrees: readonly WorktreeRecord[] = worktreeService.getRecords(),
  ): ActionContext {
      return markdownContext(card, cardTypes, 'file', worktrees);
  }
  
  /** Refresh card/file filter numbers from the current branch list without changing card metadata. */
  export function contextWithCurrentWorktree(context: ActionContext, records: readonly WorktreeRecord[]): 
ActionContext {
      if (context.kind !== 'card' && context.kind !== 'file') return context;
      if (!context.worktree && !context.worktreeError) return context;
      const assignment = actionWorktreeContext(records, context.worktree, context.worktreeBranch, 
context.worktreeError);
  
      return { ...context, ...assignment };
  }
  
  /** Build the action context for a folder node in the tree. */
  export function folderContext(folder: string, isSpecial = false): ActionContext {
      const context: ActionContext = { folder, kind: 'folder' }
      if (isSpecial) context.type = folder
  
      return context
  }
  
  /** Build context for actions that run against the opened project rather than a card or file. */
  export function projectContext(): ActionContext {
      return { kind: 'project' }
  }
  
  /** Build context for a top-level or drill-down diagram action. */

export const CARD_SEQUENCE_DROP_ID = 'card-sequence:drop'
const CARD_SEQUENCE_ITEM_PREFIX = 'card-sequence:item:'

export function cardSequenceItemId(cardInternalId: string) {
    return `${CARD_SEQUENCE_ITEM_PREFIX}${cardInternalId}`
}

export function cardInternalIdFromSequenceItem(id: string) {
    return id.startsWith(CARD_SEQUENCE_ITEM_PREFIX) ? id.slice(CARD_SEQUENCE_ITEM_PREFIX.length) : null
}

export function isCardSequenceDropId(id: string) {
    return id === CARD_SEQUENCE_DROP_ID || id.startsWith(CARD_SEQUENCE_ITEM_PREFIX)
}
